export const ANNOTATE_CSS = "/* Annotate-mode styles, served at /_glance/annotate.css and injected alongside the client.\n   Custom Highlight API paint for anchored comment ranges; span-wrap fallback uses .glance-hl. */\n::highlight(glance-comment) {\n  background-color: rgba(255, 213, 0, 0.4);\n}\n.glance-hl {\n  background-color: rgba(255, 213, 0, 0.4);\n  cursor: pointer;\n}\n\n/* Mermaid lightbox: click a rendered diagram to blow it up in a native modal <dialog>.\n   Scoped to .mermaid (mermaid's own container class) so nothing else on the page changes. */\n.mermaid svg {\n  cursor: zoom-in;\n}\ndialog.glance-lb {\n  border: 0;\n  padding: 0;\n  background: transparent;\n  width: 96vw;\n  max-width: 96vw;\n  max-height: 96vh;\n}\ndialog.glance-lb::backdrop {\n  background: rgba(8, 10, 13, 0.93);\n}\ndialog.glance-lb > div {\n  padding: 24px;\n  border-radius: 8px;\n  cursor: zoom-out;\n}\ndialog.glance-lb svg {\n  display: block;\n  width: 100% !important;\n  max-width: none !important;\n  height: auto;\n  max-height: 84vh;\n}\n\n/* Print / Save as PDF: keep the page's own background and colors. Browsers drop backgrounds when\n   printing, which turns a dark theme into pale text on white paper; `exact` is the standard\n   opt-in. The property inherits, so setting it on the root covers the whole page. */\n@media print {\n  :root {\n    -webkit-print-color-adjust: exact;\n    print-color-adjust: exact;\n  }\n}\n"
